"use client";

import { useEffect, useState } from "react";
import Link from "next/link";

import {
  UploadCloudIcon,
  SearchIcon,
  DatabaseIcon,
  FileStackIcon,
  LayersIcon,
  BrainCogIcon,
  ListChecksIcon,
} from "@/components/icons";

import { AppShell } from "@/components/shared/AppShell";
import { Button } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";

import { FeatureCard } from "@/components/dashboard/FeatureCard";
import { StatCard } from "@/components/dashboard/StatCard";
import { ActivityRow } from "@/components/dashboard/ActivityRow";

import { getDashboard } from "@/services/api";
import type { ActivityItem } from "@/types";

export default function DashboardPage() {

  const [documents, setDocuments] = useState(0);
  const [chunks, setChunks] = useState(0);
  const [embeddings, setEmbeddings] = useState(0);
  const [studyPlans, setStudyPlans] = useState(0);

  const [activity, setActivity] = useState<ActivityItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {

    async function loadDashboard() {

      try {

        const data = await getDashboard();

        setDocuments(data.documents);
        setChunks(data.chunks);
        setEmbeddings(data.embeddings);
        setStudyPlans(data.studyPlans);

        setActivity(data.activity);

      } catch (err) {

        console.error(err);

      } finally {

        setLoading(false);

      }

    }

    loadDashboard();

  }, []);

  return (
    <AppShell title="Dashboard">

      <section className="hero">
        <div className="hero-blob-a" />
        <div className="hero-blob-b" />

        <div className="hero-content">

          <h1 className="hero-title">
            AI Study Companion
          </h1>

          <p className="hero-subtitle">
            Upload your study notes and let AI create personalized study plans.
          </p>

          <Link
            href="/upload"
            className="hero-cta"
            style={{ display: "inline-block" }}
          >
            <Button
              size="lg"
              variant="primary-inverse"
            >
              <UploadCloudIcon size={18} />
              Upload Notes
            </Button>
          </Link>

        </div>

      </section>

      <section className="grid-features">

        <FeatureCard
          icon={<UploadCloudIcon size={20} />}
          title="Upload Documents"
          description="Drop PDFs or TXT files."
          href="/upload"
        />

        <FeatureCard
          icon={<BrainCogIcon size={20} />}
          title="AI Study Planner"
          description="Generate study plans."
          href="/planner"
        />

        <FeatureCard
          icon={<SearchIcon size={20} />}
          title="Smart Retrieval"
          description="Retrieve relevant notes."
          href="/planner"
        />

        <FeatureCard
          icon={<DatabaseIcon size={20} />}
          title="Qdrant Vector Search"
          description="Semantic search."
          href="/documents"
        />

      </section>

      <section className="grid-stats">

        <StatCard
          label="Documents"
          value={documents}
          icon={<FileStackIcon size={20} />}
        />

        <StatCard
          label="Chunks"
          value={chunks}
          icon={<LayersIcon size={20} />}
        />

        <StatCard
          label="Embeddings"
          value={embeddings}
          icon={<DatabaseIcon size={20} />}
        />

        <StatCard
          label="Study Plans"
          value={studyPlans}
          icon={<ListChecksIcon size={20} />}
        />

      </section>

      <section className="mt-8">

        <Card hoverLift={false}>

          <h2 className="section-title">
            Recent Activity
          </h2>

          {loading ? (

            <p>Loading...</p>

          ) : activity.length === 0 ? (

            <p>No activity yet.</p>

          ) : (

            activity.map((item, index) => (
              <ActivityRow
                key={item.id}
                item={item}
                index={index}
              />
            ))

          )}

        </Card>

      </section>

    </AppShell>
  );
}